insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('DEMO-D9-S1-001', 'source'::public.t3a_content_family, 'The summary that should lead with the exceptions', 'D9', 'not_loaded'::public.t3a_operational_state) on conflict do nothing;
insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.1', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"source_identifier": "DEMO-D9-S1-001", "title": "The summary that should lead with the exceptions", "stage": 1, "stage_code": "S1", "demonstration": true, "serving_eligible": false, "scenario_class": "observation_ready", "d9_situation_class": "SC-D9-1", "interaction_pattern_family_id": "IPF-D9-01", "administration_form_id": "AF-S1-SEQUENTIAL-REVEAL", "name_clearance_claim": "CLEARED", "compatibility_class": null, "source_sheet": {"source_sheet_text": "`situation_shown`: In the situation: \"the summary should lead with the three exceptions of the month, not with the full table.\" `current_approach`: The report format of the participant''s previous team. `indications`: IN1 the summary should lead with the month''s three exceptions. IN2 the department''s template puts exceptions first. `approach_changes`: AC1 lead the summary with the three exceptions. AC2 build the report on the department''s template. `retention_grounds`: RG1 the finance analyst uses the full table each month to reconcile the budget. `knowledge_sources`: KS1 the manager. KS2 the department''s report template. KS3 the finance analyst. `open_points`: OP1 where the full table sits in the template. OP2 how the manager selects the three exceptions. `trial_steps`: TS1 send the manager the revised summary page before the full report. `next_work`: NW1 Friday''s report. NW2 the monthly reports after it. `record_place`: The department''s report procedure. `practice_origin`: The participant''s previous team used a different report format. `account_test_point`: R8. `account_test_record`: The situation records that the department''s template puts exceptions first.", "d9_situation_class": "SC-D9-1"}, "question_applicability": [{"question": "Q-D9-01", "state": "DIRECT", "basis": "Indications set out"}, {"question": "Q-D9-01b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-02", "state": "DIRECT", "basis": "Changes to the approach listed"}, {"question": "Q-D9-02b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-03", "state": "DIRECT", "basis": "Grounds for keeping the approach recorded"}, {"question": "Q-D9-03b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-04", "state": "DIRECT", "basis": "Sources of knowledge listed"}, {"question": "Q-D9-04b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-05", "state": "DIRECT", "basis": "Open points set out"}, {"question": "Q-D9-05b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-06", "state": "DIRECT", "basis": "Trial steps listed"}, {"question": "Q-D9-06b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-07", "state": "DIRECT", "basis": "Items of work ahead set out"}, {"question": "Q-D9-07b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-08", "state": "DIRECT", "basis": "A record place exists"}, {"question": "Q-D9-09", "state": "DIRECT", "basis": "The account test at R8 puts an earlier statement back"}], "script": null, "reveals": [], "text_blocks": {"The situation as the participant meets it": "You prepare the monthly operations report for your department. Your manager returned your first report with a note: the summary should lead with the three exceptions of the month, not with the full table.\nWhat the record shows: the department''s report template puts exceptions first; your report followed the format of the team you worked in before; the finance analyst uses the full table each month to reconcile the budget; the next report is due on Friday; and the template is on the shared drive."}, "narrative": {"The situation as the participant meets it": "> You prepare the monthly operations report for your department. Your manager returned your first report with a note: the summary should lead with the three exceptions of the month, not with the full table.\n>\n> What the record shows: the department''s report template puts exceptions first; your report followed the format of the team you worked in before; the finance analyst uses the full table each month to reconcile the budget; the next report is due on Friday; and the template is on the shared drive.", "Reveal sequence": "R1 the situation. R2 QUESTION: what does the note tell you about the report, and what do you do next? R3 QUESTION: what, if anything, do you change in how you prepare it, and what do you keep as it is? Why? R4 QUESTION: who or what do you go to, and what do you ask? R5 QUESTION: before you rely fully on a different way of doing it, what, if anything, do you do first? R6 QUESTION: which work ahead does your approach apply to, and from when? R7 QUESTION: what, if anything, gets written down, and where? R8 ACCOUNT TEST: your manager writes, \"You said the template puts the table first. Does it?\" — QUESTION: what do you say?", "What this fixture proves": "A participant may state a change to one part of the approach and keep another. Selected together, Q-D9-02 A1 and Q-D9-03 A1 BOTH compose, render side by side, and neither is styled, ordered or worded as the conclusion. A build that suppresses either, or that renders the kept approach as a qualification of the change, has failed Section 5.14. practice_origin appears nowhere in the capture screen or the report."}, "source_version_hash": "a0001f4eaae2342edc565cbb6d10d344ee971bfe3a19e1174d7a7bbecdb11c26"}'::jsonb from public.t3a_content_object where identifier = 'DEMO-D9-S1-001' and not exists (select 1 from public.t3a_d1_content_version v where v.content_object_id = t3a_content_object.content_object_id);
