insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('DEMO-D9-S2-001', 'source'::public.t3a_content_family, 'The manual count the scanner was meant to replace', 'D9', 'not_loaded'::public.t3a_operational_state) on conflict do nothing;
insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.1', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"source_identifier": "DEMO-D9-S2-001", "title": "The manual count the scanner was meant to replace", "stage": 2, "stage_code": "S2", "demonstration": true, "serving_eligible": false, "scenario_class": "observation_ready", "d9_situation_class": "SC-D9-7", "interaction_pattern_family_id": "IPF-D9-07", "administration_form_id": "AF-S2-SEVEN-BEAT", "name_clearance_claim": "CLEARED", "compatibility_class": null, "source_sheet": {"source_sheet_text": "`situation_shown`: In the pre-brief: \"it miscounted mixed pallets twice in its first month.\" `current_approach`: The weekly manual stock count. `indications`: IN1 the scanner miscounted mixed pallets twice. IN2 the scanner reads single product pallets correctly. `approach_changes`: AC1 count single product pallets with the scanner. AC2 replace the manual count with the scanner. `retention_grounds`: RG1 the manual count found three discrepancies last month. `knowledge_sources`: KS1 the scanner''s vendor. KS2 the warehouse supervisor. `open_points`: OP1 why the scanner miscounts mixed pallets. `trial_steps`: TS1 run the scanner alongside the manual count on Monday and compare. `next_work`: NW1 Monday''s count. NW2 the weekly counts after it. `record_place`: The count procedure. `practice_origin`: None. `account_test_point`: B6. `account_test_record`: The situation records that the scanner miscounted mixed pallets twice.", "d9_situation_class": "SC-D9-7"}, "question_applicability": [{"question": "Q-D9-01", "state": "DIRECT", "basis": "Indications set out"}, {"question": "Q-D9-01b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-02", "state": "DIRECT", "basis": "Changes to the approach listed"}, {"question": "Q-D9-02b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-03", "state": "DIRECT", "basis": "Grounds for keeping the approach recorded"}, {"question": "Q-D9-03b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-04", "state": "DIRECT", "basis": "Sources of knowledge listed"}, {"question": "Q-D9-04b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-05", "state": "DIRECT", "basis": "Open points set out"}, {"question": "Q-D9-05b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-06", "state": "DIRECT", "basis": "Trial steps listed"}, {"question": "Q-D9-06b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-07", "state": "DIRECT", "basis": "Items of work ahead set out"}, {"question": "Q-D9-07b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-08", "state": "DIRECT", "basis": "A record place exists"}, {"question": "Q-D9-09", "state": "DIRECT", "basis": "The account test at B6 puts an earlier statement back"}], "script": null, "reveals": [], "text_blocks": {}, "narrative": {"Participant pre-brief": "You run the weekly stock count at a distribution warehouse by hand. A colleague says the new handheld scanner makes the manual count unnecessary. What the record shows: the scanner reads single product pallets correctly; it miscounted mixed pallets twice in its first month; the manual count found three discrepancies last month; the scanner saves about two hours per count; the scanner''s vendor runs a setup session on request; and the next count is on Monday.", "Mentor brief": "The mentor reads the scripted lines of the warehouse supervisor. **THE MENTOR FORMS NO VIEW OF HOW READILY THE PARTICIPANT TAKES IN WHAT IS NEW AND RECORDS NOTHING ABOUT IT, INCLUDING THAT THEY SEEMED KEEN OR RELUCTANT.**", "The four questions": "B3 — \"What does this tell you about the work, and what, if anything, do you change or keep in how you do it?\" B4 — \"Who or what are you going to, what would you ask, and would you try anything out first?\" B5 — \"Which work does your approach apply to, from when, and what goes on the record?\" B6 — \"Just so I have it right — you said the scanner reads mixed pallets correctly. Does it?\"", "What this fixture proves": "A participant who states that the manual count is to be kept, and names the three discrepancies as the ground, receives ST-D9-011 and the selection ST-D9-015, with NO adverse clause and nothing composed for Q-D9-02. Keeping an approach is recorded exactly as a change would be: as what was stated. A build that renders any frame, label or note implying the participant declined to change has failed Section 3.2."}, "source_version_hash": "75dbfbc2492c9a4cd72ca061d4c3c6f76aa46dfd42cec85171d68583c5d64628"}'::jsonb from public.t3a_content_object where identifier = 'DEMO-D9-S2-001' and not exists (select 1 from public.t3a_d1_content_version v where v.content_object_id = t3a_content_object.content_object_id);
