insert into public.t3a_source_drafting_test(source_version_id, test_no, outcome, reviewer_identity, tested_on, version_tested_ref) select v.content_version_id, 2, 'demonstration_only', 'DEMONSTRATION_REVIEWER', current_date, v.version_no from public.t3a_d1_content_version v join public.t3a_content_object o using (content_object_id) where o.identifier = 'DEMO-D9-S2-001' on conflict do nothing;
insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('DEMO-D9-S3-001', 'source'::public.t3a_content_family, 'The onboarding guide two steps short', 'D9', 'not_loaded'::public.t3a_operational_state) on conflict do nothing;
insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.1', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"source_identifier": "DEMO-D9-S3-001", "title": "The onboarding guide two steps short", "stage": 3, "stage_code": "S3", "demonstration": true, "serving_eligible": false, "scenario_class": "work_sample", "d9_situation_class": "SC-D9-2", "interaction_pattern_family_id": "IPF-D9-02", "administration_form_id": "AF-S3-ASYNC-SUBMISSION", "name_clearance_claim": "CLEARED", "compatibility_class": null, "source_sheet": {"source_sheet_text": "`situation_shown`: In the brief: \"each missed the same two steps when closing a ticket.\" `current_approach`: The onboarding guide as written. `indications`: IN1 the first five new staff each missed the same two steps. IN2 the closing screen lists the steps in a different order from the guide. `approach_changes`: AC1 move the two steps to the guide''s first page. AC2 match the guide''s order to the closing screen. `retention_grounds`: RG1 the guide''s search section was used by all five. `knowledge_sources`: KS1 the system administrator. KS2 the five new staff. `open_points`: OP1 why the closing screen''s order differs from the guide. `trial_steps`: TS1 give the revised page to two of the five before the second group starts. `next_work`: NW1 the second group in two weeks. `record_place`: The guide''s revision history. `practice_origin`: None.", "d9_situation_class": "SC-D9-2"}, "question_applicability": [{"question": "Q-D9-01", "state": "DIRECT", "basis": "Indications set out"}, {"question": "Q-D9-01b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-02", "state": "DIRECT", "basis": "Changes to the approach listed"}, {"question": "Q-D9-02b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-03", "state": "DIRECT", "basis": "Grounds for keeping the approach recorded"}, {"question": "Q-D9-03b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-04", "state": "DIRECT", "basis": "Sources of knowledge listed"}, {"question": "Q-D9-04b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-05", "state": "DIRECT", "basis": "Open points set out"}, {"question": "Q-D9-05b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-06", "state": "DIRECT", "basis": "Trial steps listed"}, {"question": "Q-D9-06b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-07", "state": "DIRECT", "basis": "Items of work ahead set out"}, {"question": "Q-D9-07b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-08", "state": "DIRECT", "basis": "A record place exists"}, {"question": "Q-D9-09", "state": "NOT SERVED", "basis": "The asynchronous form puts no earlier statement back"}], "script": null, "reveals": [], "text_blocks": {"The brief as the participant meets it": "You wrote the onboarding guide for the customer support team''s ticketing system. The first five new staff to use it each missed the same two steps when closing a ticket.\nWhat the record shows: the two steps sit on the second page of the guide; the system''s own closing screen lists the steps in a different order from the guide; the guide''s search section was used by all five; the system administrator can change the closing screen''s order; and a second group of new staff starts in two weeks.\nProduce what the first group''s results show, what you would change and keep in the guide, and how you would check the guide before the second group starts."}, "narrative": {"The brief as the participant meets it": "> You wrote the onboarding guide for the customer support team''s ticketing system. The first five new staff to use it each missed the same two steps when closing a ticket.\n>\n> What the record shows: the two steps sit on the second page of the guide; the system''s own closing screen lists the steps in a different order from the guide; the guide''s search section was used by all five; the system administrator can change the closing screen''s order; and a second group of new staff starts in two weeks.\n>\n> Produce what the first group''s results show, what you would change and keep in the guide, and how you would check the guide before the second group starts.", "Submission": "Asynchronous. `min_seconds`, `max_seconds` and `mentor_action_sequence` NULL — null is not an error. Eleven provenance fields, three declarations, AI_USE_DECLARATION_REQUIRED in force.", "What this fixture proves": "Q-D9-09 produces no row of any kind while the other eight elements are served from the submission. A build that writes a null, a `not_applicable` or a \"not observed\" sentence for Q-D9-09 has failed."}, "source_version_hash": "1ac5dbab43f52b7e469f91c5f24f860dc434af4711995eafbe27240f46b76d75"}'::jsonb from public.t3a_content_object where identifier = 'DEMO-D9-S3-001' and not exists (select 1 from public.t3a_d1_content_version v where v.content_object_id = t3a_content_object.content_object_id);
