insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('DEMO-D9-S4-001', 'source'::public.t3a_content_family, 'The scheduling tool the planners have not used', 'D9', 'not_loaded'::public.t3a_operational_state) on conflict do nothing;
insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.1', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"source_identifier": "DEMO-D9-S4-001", "title": "The scheduling tool the planners have not used", "stage": 4, "stage_code": "S4", "demonstration": true, "serving_eligible": false, "scenario_class": "team_simulation", "d9_situation_class": "SC-D9-3", "interaction_pattern_family_id": "IPF-D9-03", "administration_form_id": "AF-S4-GROUP-ROUND", "name_clearance_claim": "CLEARED", "compatibility_class": null, "source_sheet": {"source_sheet_text": "`situation_shown`: In the pre-brief: \"the tool''s first draft schedule left two weekend shifts uncovered.\" `current_approach`: Shift scheduling in spreadsheets. `indications`: IN1 the tool''s first draft left two weekend shifts uncovered. `approach_changes`: AC1 configure the tool with the rest rules before the next draft. AC2 schedule in the tool from the first of next month. `retention_grounds`: RG1 the spreadsheet schedule has covered every shift this year. `knowledge_sources`: KS1 the vendor''s configuration session. KS2 the planner at another site. `open_points`: OP1 why the draft left the weekend shifts uncovered. `trial_steps`: TS1 run next month''s schedule in the tool and the spreadsheet side by side. `next_work`: NW1 next month''s schedule. `record_place`: The planning procedure. `practice_origin`: None. `account_test_point`: B6. `account_test_record`: The situation records that the first draft left two weekend shifts uncovered.", "d9_situation_class": "SC-D9-3"}, "question_applicability": [{"question": "Q-D9-01", "state": "DIRECT", "basis": "Indications set out"}, {"question": "Q-D9-01b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-02", "state": "DIRECT", "basis": "Changes to the approach listed"}, {"question": "Q-D9-02b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-03", "state": "DIRECT", "basis": "Grounds for keeping the approach recorded"}, {"question": "Q-D9-03b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-04", "state": "DIRECT", "basis": "Sources of knowledge listed"}, {"question": "Q-D9-04b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-05", "state": "DIRECT", "basis": "Open points set out"}, {"question": "Q-D9-05b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-06", "state": "DIRECT", "basis": "Trial steps listed"}, {"question": "Q-D9-06b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-07", "state": "DIRECT", "basis": "Items of work ahead set out"}, {"question": "Q-D9-07b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-08", "state": "DIRECT", "basis": "A record place exists"}, {"question": "Q-D9-09", "state": "DIRECT", "basis": "The account test at B6 puts an earlier statement back"}], "script": null, "reveals": [], "text_blocks": {}, "narrative": {"Model": "ONE OBSERVED PARTICIPANT (P-OBS), THREE CO-PARTICIPANTS (CP-1, CP-2, CP-3) who are role players and are NOT observed, one facilitator. ONE OBSERVATION RECORD, for P-OBS only. A Stage 4 group participation record is required for all four before entry. No recording.", "P-OBS pre-brief": "Your planning team must move shift scheduling from spreadsheets to a new scheduling tool by the first of next month. What the record shows: the tool''s first draft schedule left two weekend shifts uncovered; the spreadsheet schedule has covered every shift this year; the tool''s vendor offers a configuration session; a planner at another site has used the tool for a year; and the union agreement''s rest rules must hold in any schedule.", "CP positions": "CP-1, operations: state the first of next month as the date. CP-2, a planner: state that the spreadsheet schedule has covered every shift this year. CP-3, the vendor''s contact: state that a configuration session is available.", "Facilitator card": "As Section 5.18, including: **RECORD ONLY WHAT WAS SAID ABOUT THE APPROACH TO THE WORK. NOTHING ABOUT ANY PERSON IN THE ROOM IS RECORDABLE, INCLUDING HOW READILY ANYONE TOOK IN WHAT WAS NEW.**", "The four questions": "B3 — \"What does this tell you about the work, and what, if anything, do you change or keep in how you do it?\" B4 — \"Who or what are we going to, what would we ask, and would we try anything out first?\" B5 — \"Which work does the approach apply to, from when, and what goes on the record?\" B6 — \"Just so we have it right — you said the draft covered every shift. Did it?\"", "What this fixture proves": "CP-2 restates the retention ground and CP-3 the vendor session, both already established by the pre-brief. **THE PRE-BRIEF AND SOURCE SHEET ESTABLISH THEM; THE CO-PARTICIPANTS DO NOT.** A build that lets a co-participant position populate `indications`, `approach_changes`, `retention_grounds` or `knowledge_sources` will pass the other three fixtures and fail here."}, "source_version_hash": "c373e8994eb722ec13c1ac71bb817886f9f1f993dc036574c04758312d0473e5"}'::jsonb from public.t3a_content_object where identifier = 'DEMO-D9-S4-001' and not exists (select 1 from public.t3a_d1_content_version v where v.content_object_id = t3a_content_object.content_object_id);
insert into public.t3a_source_authorship(source_version_id, source_author_identity) select v.content_version_id, array['DEMONSTRATION_AUTHOR'] from public.t3a_d1_content_version v join public.t3a_content_object o using (content_object_id) where o.identifier = 'DEMO-D9-S4-001' on conflict do nothing;
insert into public.t3a_source_drafting_test(source_version_id, test_no, outcome, reviewer_identity, tested_on, version_tested_ref) select v.content_version_id, 1, 'demonstration_only', 'DEMONSTRATION_REVIEWER', current_date, v.version_no from public.t3a_d1_content_version v join public.t3a_content_object o using (content_object_id) where o.identifier = 'DEMO-D9-S4-001' on conflict do nothing;
insert into public.t3a_source_drafting_test(source_version_id, test_no, outcome, reviewer_identity, tested_on, version_tested_ref) select v.content_version_id, 2, 'demonstration_only', 'DEMONSTRATION_REVIEWER', current_date, v.version_no from public.t3a_d1_content_version v join public.t3a_content_object o using (content_object_id) where o.identifier = 'DEMO-D9-S4-001' on conflict do nothing;
